  mk("\u672C\u6708\u652F\u51FA", s.monthlyExpense, "expense");
  mk("\u672C\u6708\u76C8\u4E8F", s.monthlyProfit, s.monthlyProfit >= 0 ? "income" : "expense");
  mk("\u672C\u6708\u9884\u7B97", b.monthlyBudget);
