function timeOf(ts) {
  const d = new Date(ts);
  const h = String(d.getHours()).padStart(2, "0");
  const m = String(d.getMinutes()).padStart(2, "0");
  return `${h}:${m}`;
}

// app/src/kanban/sync.ts
function sanitize(name) {
  return name.replace(/[\\/:*?"<>|]/g, "-").replace(/\s+/g, " ").trim() || "\u672A\u547D\u540D";
}
function yamlFrontmatter(obj) {
  let s = "---\n";
  for (const [k, v] of Object.entries(obj)) {
    if (Array.isArray(v)) s += `${k}: [${v.join(", ")}]
`;
    else if (typeof v === "string") s += `${k}: ${JSON.stringify(v)}
`;
    else s += `${k}: ${v}
`;
  }
  s += "---\n";
  return s;
}
async function ensureFolder(plugin, path) {
  const adapter = plugin.app.vault.adapter;
  const parts = path.split("/").filter(Boolean);
  let cur = "";
  for (const p of parts) {
    cur = cur ? `${cur}/${p}` : p;
    const f = plugin.app.vault.getAbstractFileByPath(cur);
    if (!f && !await adapter.exists(cur)) await plugin.app.vault.createFolder(cur);
  }
}
async function findNoteByKanbanId(plugin, basePath, id) {
  const folder = plugin.app.vault.getAbstractFileByPath(basePath);
  if (!(folder instanceof TFolder)) return null;
  for (const child of folder.children) {
    if (child instanceof TFile && child.extension === "md") {
      const cache = plugin.app.metadataCache.getFileCache(child);
      if (cache?.frontmatter?.kanbanId === id) return child;
    }
  }
  return null;
}
async function writeNote(plugin, basePath, kanbanId, fileNameBase, content) {
  const targetName = `${sanitize(fileNameBase)}.md`;
  let targetPath = `${basePath}/${targetName}`;
  const existing = await findNoteByKanbanId(plugin, basePath, kanbanId);
  const collision = plugin.app.vault.getAbstractFileByPath(targetPath);
  if (collision && collision.path !== existing?.path) {
    const stem = sanitize(fileNameBase) + "-" + sanitize(kanbanId);
    targetPath = `${basePath}/${stem}.md`;
    let suffix = 2;
    while (plugin.app.vault.getAbstractFileByPath(targetPath) && targetPath !== existing?.path) targetPath = `${basePath}/${stem}-${suffix++}.md`;
  }
  if (existing) {
    if (existing.path !== targetPath) {
      await plugin.app.vault.rename(existing, targetPath);
    }
    const file = plugin.app.vault.getAbstractFileByPath(targetPath);
    if (file instanceof TFile) await plugin.app.vault.modify(file, content);
  } else {
    await plugin.app.vault.create(targetPath, content);
  }
}
function projectBody(p, tasks) {
  const lines = [];
  lines.push(`# ${p.name}`, "");
  lines.push(`> \u5206\u7C7B\uFF1A${p.category} \xB7 \u4F18\u5148\u7EA7\uFF1A${p.priority}` + (p.tags.length ? ` \xB7 \u6807\u7B7E\uFF1A${p.tags.join(", ")}` : ""), "");
  if (p.description) lines.push(p.description, "");
  const prog = projectProgress(tasks, p.id);
  lines.push(`## \u4EFB\u52A1\uFF08${prog.done}/${prog.total}\uFF09`, "");
  if (tasks.length === 0) {
    lines.push("_\u6682\u65E0\u4EFB\u52A1_", "");
  } else {
    for (const t2 of tasks) {
      const box = taskIsDone(t2) ? "x" : " ";
      const archTag = t2.archived ? " \xB7 \u5DF2\u5F52\u6863" : "";
      lines.push(`- [${box}] ${t2.name}\uFF08${t2.priority} \xB7 ${taskStatusLabel(t2)}${archTag}\uFF09`);
      const subs = taskSubtasks(t2);
      if (subs.length > 0) {
        const tp = taskProgress(t2);
        for (const s of subs) {
          const sbox = s.done ? "x" : " ";
          lines.push(`  - [${sbox}] ${s.name}\uFF08${s.current || 0}/${s.target}\uFF09`);
        }
        lines.push(`  - _\u5B50\u9879\u8FDB\u5EA6 ${tp.pct}%_`);
      }
    }
    lines.push("");
  }
  return lines.join("\n");
}
function taskBody(t2) {
  const parts = [];
  if (t2.note) parts.push(t2.note);
  else parts.push("_\uFF08\u65E0\u5907\u6CE8\uFF09_");
  const subs = taskSubtasks(t2);
  if (subs.length > 0) {
    const tp = taskProgress(t2);
    parts.push("", `## \u5B50\u9879\uFF08${tp.pct}%\uFF09`, "");
    for (const s of subs) {
      const sbox = s.done ? "x" : " ";
      parts.push(`- [${sbox}] ${s.name}\uFF08${s.current || 0}/${s.target}\uFF09`);
    }
  }
  return parts.join("\n") + "\n";
}
async function syncToVault(plugin) {
  const store = plugin.store;
  const basePath = store.getSettings().vaultPath || "02-\u957F\u671F\u9886\u57DF/03\u4EFB\u52A1\u770B\u677F";
  await ensureFolder(plugin, basePath);
  for (const p of store.getProjects()) {
    const tasks = store.getTasksOfProject(p.id);
    const content = yamlFrontmatter({
      kanbanId: p.id,
      type: "kanban-project",
      name: p.name,
      category: p.category,
      priority: p.priority,
      startDate: p.startDate,
      due: p.dueDate,
      created: new Date(p.createdAt).toISOString().slice(0, 10),
      tags: ["\u770B\u677F", "\u9879\u76EE", ...p.tags]
    }) + "\n" + projectBody(p, tasks);
    await writeNote(plugin, basePath, p.id, `\u9879\u76EE-${p.name}`, content);
  }
  for (const t2 of store.getTasks()) {
    if (t2.projectId) continue;
    const content = yamlFrontmatter({
      kanbanId: t2.id,
      type: "kanban-task",
      name: t2.name,
      done: t2.done,
      archived: t2.archived,
      // 优化-009
      completedAt: t2.completedAt,
      // 优化-009
      progress: taskProgress(t2).pct,
      priority: t2.priority,
      due: t2.dueDate,
      created: new Date(t2.createdAt).toISOString().slice(0, 10),
      tags: ["\u770B\u677F", "\u4EFB\u52A1", ...t2.tags]
    }) + "\n" + taskBody(t2);
    await writeNote(plugin, basePath, t2.id, `\u4EFB\u52A1-${t2.name}`, content);
  }
  const result = {
    projects: store.getProjects().length,
    tasks: store.getTasks().filter((t2) => !t2.projectId).length,
    path: basePath
  };
  new Notice(`\u5DF2\u540C\u6B65 ${result.projects} \u4E2A\u9879\u76EE / ${result.tasks} \u4E2A\u6E38\u79BB\u4EFB\u52A1 \u2192 ${basePath}`);
  return result;
}

